INSERT INTO `services` (`id`, `title`, `slug`, `icon`, `short_description`, `full_description`, `features`, `target_audience`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('1', 'Dissertation & Thesis Coaching', 'dissertation-thesis-coaching', 'fas fa-graduation-cap', '1-on-1 personalized guidance for thesis proposal drafting, research methodology design, and defense preparation.', 'Comprehensive mentorship tailored for Master\'s and PhD candidates. Detailed guidance is provided for literature gap identification, research question formulation, methodology selection, data collection strategy, and defense slide deck optimization.', '[\"Proposal Structuring & Review\",\"Theoretical Framework Alignment\",\"Defense Mock Sessions & Q&A Prep\",\"IRB \\/ Ethics Committee Guidance\"]', 'PhD Candidates & Master\'s Researchers', '1', '1', '2026-08-24 13:49:02', '2026-08-24 13:49:02');
INSERT INTO `services` (`id`, `title`, `slug`, `icon`, `short_description`, `full_description`, `features`, `target_audience`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('2', 'Systematic Literature Review & Meta-Analysis Consulting', 'systematic-literature-review-meta-analysis-consulting', 'fas fa-book-open', 'End-to-end guidance on PRISMA guidelines, protocol registration, search matrix, data extraction & meta-analytic modeling.', 'Transform scattered literature into high-impact systematic reviews. Structured advisory covers PRISMA 2020 compliance, database search strings (Scopus, Web of Science, PubMed), quality appraisal tools, and effect size synthesis.', '[\"PRISMA 2020 Compliant Protocol\",\"Search String & Database Strategy\",\"Risk of Bias & Quality Appraisal\",\"Bibliometric & Meta-Analysis Setup\"]', 'Academic Researchers & Faculty', '1', '2', '2026-08-24 13:49:02', '2026-08-24 13:49:02');
INSERT INTO `services` (`id`, `title`, `slug`, `icon`, `short_description`, `full_description`, `features`, `target_audience`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('3', 'Scientific Paper Writing & Journal Submission Support', 'scientific-paper-writing-journal-submission-support', 'fas fa-feather-alt', 'Expert editing, journal targeting, response to reviewers, and structural polishing for Scopus & WOS indexed journals.', 'Maximize your publication success rate in top-tier journals (SSCI, SCI, Scopus Q1/Q2). Receive detailed review of your manuscript structure, Academic English flow, reviewer response letter drafting, and journal matching.', '[\"Journal Selection & Impact Matching\",\"Pre-submission Peer Review\",\"Response to Reviewers Drafting\",\"Academic English & Style Refinement\"]', 'Early & Mid-career Researchers', '1', '3', '2026-08-24 13:49:02', '2026-08-24 13:49:02');
INSERT INTO `services` (`id`, `title`, `slug`, `icon`, `short_description`, `full_description`, `features`, `target_audience`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('4', 'Grant Writing & Research Advisory', 'grant-writing-research-advisory', 'fas fa-award', 'Consultancy for national and international research grant applications (HEC, Ministry grants, international funds).', 'Securing competitive research funding requires a compelling narrative, realistic budget breakdown, clear milestone matrix, and demonstrated societal impact. Leverage Dr. Shakil\'s track record in securing grants from Oman MoHESR and HEC Pakistan.', '[\"Grant Proposal Concept Notes\",\"Budget & Milestones Planning\",\"Societal & Economic Impact Framing\",\"ORIC \\/ Institutional Alignment\"]', 'Universities & Institutional PIs', '1', '4', '2026-08-24 13:49:02', '2026-08-24 13:49:02');
INSERT INTO `services` (`id`, `title`, `slug`, `icon`, `short_description`, `full_description`, `features`, `target_audience`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('5', '1-on-1 Academic & Career Life Coaching', '1-on-1-academic-career-life-coaching', 'fas fa-user-tie', 'Personalized executive coaching to overcome academic burnout, establish career direction, and build academic brand.', 'Tailored coaching sessions focusing on productivity systems, research career roadmap, managing academic stress, building ORCID / Google Scholar visibility, and achieving work-life balance in higher education.', '[\"Academic Career Roadmap\",\"Burnout & Productivity Coaching\",\"Personal Academic Branding\",\"Time Management & Focus Frameworks\"]', 'Academicians & Corporate Executives', '1', '5', '2026-08-24 13:49:02', '2026-08-24 13:49:02');
